"""Complete 36 original shock/hemodynamic support questions."""
from create_critical_shock_types import rows,q,HE,SS,CS,PE,PC,ref
from qbank_authoring import finalize
AR=ref('Arterial catheter blood-pressure measurement: systematic approach','https://pmc.ncbi.nlm.nih.gov/articles/PMC7183114/')

q('Which vasopressor is the usual first-line choice for septic shock requiring vasopressor support?', 'Norepinephrine',[
 ('Dopamine','It carries greater arrhythmia concerns and is not the routine first-line agent.'),('Phenylephrine','Pure alpha stimulation is not the standard default in septic shock.'),('Dobutamine','This is primarily an inotrope and can worsen hypotension without appropriate vascular support.')],
 'Restore vascular tone with an evidence-based first choice','**Norepinephrine is recommended as first-line vasopressor in septic shock.**',['Treatment can begin promptly while volume status and the cause are assessed.','Selected phenotypes may need an additional agent or inotropic support.'], '**Titrate to a perfusion-oriented pressure goal.**',['Monitor rhythm, ischemic adverse effects and tissue perfusion.','Do not regard pressure restoration as completion of source and organ management.'],[['Norepinephrine','First-line vasopressor'],['Dobutamine','Selected low-output support'],['Dopamine','Greater arrhythmia concern']],[SS])

q('Under the 2026 Surviving Sepsis Campaign, what initial MAP range is suggested for many septic shock patients aged at least 65 years, subject to individual perfusion assessment?', '60–65 mmHg',[
 ('45–50 mmHg','This is below the suggested range and may jeopardize organ perfusion.'),('75–80 mmHg for every older patient','Higher targets are not the default suggestion for all older patients.'),('90–100 mmHg for every older patient','This can add unnecessary vasopressor exposure without a universal benefit.')],
 'State the age-specific recommendation accurately','**SSC 2026 conditionally suggests an initial sixty-to-sixty-five range in patients at least sixty-five years old.**',['This is not a rule to ignore cerebral, coronary or renal perfusion needs.','Higher targets can be appropriate in selected individual circumstances.'], '**Reassess clinical perfusion and adverse effects.**',['Use an accurate pressure measurement.','Do not extrapolate this target to hemorrhage, neurotrauma or other shock syndromes.'],[['Older septic shock','Suggested initial MAP 60–65'],['Individual factors','Can alter the target'],['Other shock syndromes','Need their own target framework']],[SS])

q('A septic patient has persistent hypotension with escalating norepinephrine needs after appropriate reassessment. Which adjunct is commonly added to reduce catecholamine escalation?', 'Vasopressin',[
 ('Nitroglycerin','This generally reduces vascular tone and can worsen hypotension.'),('Dobutamine solely as a vasoconstrictor','Its main role is inotropy and it can lower resistance.'),('Furosemide solely as a pressor','It does not provide vasoconstrictor support and needs a separate fluid-management indication.')],
 'Use a complementary vasoconstrictor pathway','**Vasopressin is a common adjunct to norepinephrine in septic shock.**',['It does not replace reassessment of ongoing hypovolemia, pump dysfunction or obstruction.','Excess vasoconstriction can cause ischemic harm.'], '**Treat the reason for refractory shock rather than only add drugs.**',['Review source control, infection treatment, acid-base status and ventricular function.','Use subsequent escalation according to response and current guidance.'],[['Norepinephrine','Catecholamine pathway'],['Vasopressin','Complementary V1-mediated support'],['Refractory shock','Reassess the mechanism']],[SS],style='clinical_scenario')

q('After adequate arterial pressure and volume assessment, a septic patient has persistent hypoperfusion and depressed cardiac output on echo. Which strategy may be appropriate?', 'A monitored inotropic strategy such as dobutamine added to norepinephrine, or an appropriate epinephrine strategy',[
 ('Escalating vasoconstriction without considering flow','Higher afterload may not correct and can worsen a low-output component.'),('Repeated fluid boluses despite rising congestion and no responsiveness','This can add edema without increasing effective flow.'),('A beta-blocker bolus before defining the low-output mechanism','This is not the usual initial strategy for pump-related hypoperfusion and can be harmful.')],
 'Pressure and flow may require different interventions','**Selected septic myocardial dysfunction with hypoperfusion can justify inotropic support.**',['Low ejection fraction alone does not automatically require an inotrope if perfusion is adequate.','Monitor tachyarrhythmia, ischemia and the actual flow/perfusion response.'], '**Stop or adjust a drug that provides no benefit or causes harm.**',['Reassess for dynamic LVOTO or another mechanism when response is paradoxical.','Treat infection and other causes concurrently.'],[['Pressure support','Maintains perfusion gradient'],['Inotropy','Can improve selected low-output states'],['Endpoint','Clinical/flow benefit, not EF alone']],[SS,HE],style='clinical_scenario')

q('A patient needs urgent norepinephrine but central access is not yet available. What is the recommended general principle?', 'Begin through a suitable closely monitored peripheral IV rather than delay necessary vasopressor support solely for central access',[
 ('Withhold all vasopressors until a central line is inserted','This can prolong dangerous hypotension.'),('Use any unobserved peripheral cannula indefinitely at any dose','Peripheral use still requires an appropriate protocol and surveillance.'),('Replace norepinephrine with an intramuscular injection for septic shock','This is not the standard septic vasopressor infusion strategy.')],
 'Access planning must not prolong circulatory failure','**Current sepsis guidance supports timely peripheral initiation when needed.**',['Use a reliable line, monitor the site and have an extravasation response plan.','The optimal size, site, duration and dose limits are not established by one universal evidence-based number.'], '**Arrange ongoing access according to trajectory and local protocol.**',['Do not confuse an appropriate monitored bridge with unrestricted peripheral use.','Verify delivery and line patency if the expected response is absent.'],[['Urgency','Do not delay necessary support'],['Peripheral use','Needs monitoring/protocol'],['Ongoing plan','Adapt to dose and duration']],[SS])

q('An arterial waveform becomes overdamped. Which pattern is most likely?', 'Underestimated systolic pressure and overestimated diastolic pressure, with MAP often less affected',[
 ('Overestimated systolic and underestimated diastolic pressure','That is more typical of underdamping/resonance.'),('A reliably exaggerated pulse pressure','Overdamping usually narrows rather than exaggerates pulse pressure.'),('A guaranteed accurate waveform because the MAP is displayed','A displayed number does not prove adequate system dynamics.')],
 'Verify the measurement before escalating treatment','**Overdamping blunts the arterial waveform.**',['Air, clot, tubing and setup problems can contribute.','A fast-flush test and system inspection help assess dynamic response.'], '**Compare with the clinical state and another pressure measurement when needed.**',['Correct the cause rather than titrate drugs to a faulty waveform.','MAP is relatively robust, not immune to every measurement error.'],[['Overdamping','Narrowed pulse pressure'],['Underdamping','Exaggerated pulse pressure'],['Action','Check line/system and patient']],[AR])

q('An arterial-pressure transducer is moved 20 cm above the reference level without releveling. What error is expected?', 'The displayed pressure will be approximately 15 mmHg too low',[
 ('The displayed pressure will be approximately 15 mmHg too high','A higher transducer produces a lower hydrostatic reading.'),('There is no error if it was zeroed earlier','Zeroing does not compensate for later height changes.'),('Only the heart rate changes','The height error affects pressure, not the measured pulse frequency.')],
 'Level and zero are separate requirements','**A ten-centimeter height difference corresponds to roughly 7.5 mmHg.**',['Twenty centimeters therefore produces about a fifteen-mmHg error.','The chosen reference must match the physiological pressure question.'], '**Relevel after repositioning the patient or transducer.**',['Do not increase vasopressors from an unrecognized low reading.','Confirm the waveform quality and calibration setup.'],[['Above reference','Pressure falsely low'],['Below reference','Pressure falsely high'],['20 cm','About 15 mmHg error']],[AR],style='clinical_scenario')

q('Hb is 8 g/dL, arterial saturation is 100% and PaO2 is 100 mmHg. Using 1.34 mL O2/g Hb, what is the approximate arterial oxygen content?', '11 mL O2/dL',[
 ('8 mL O2/dL','This omits the hemoglobin oxygen-binding coefficient.'),('20 mL O2/dL','This would be more typical of a substantially higher hemoglobin.'),('100 mL O2/dL','PaO2 is not the same as total oxygen content.')],
 'Normal saturation does not imply normal oxygen content','**CaO2 is approximately 1.34 × Hb × SaO2 plus 0.003 × PaO2.**',['The calculation is 10.72 plus 0.3, or about eleven mL/dL.','Most oxygen is hemoglobin-bound, not dissolved.'], '**Assess delivery using both content and flow.**',['Transfusion decisions depend on the syndrome and risks, not this calculation alone.','A normal pulse oximeter can coexist with low oxygen-carrying capacity.'],[['Hemoglobin-bound','About 10.7 mL/dL'],['Dissolved','About 0.3 mL/dL'],['Total','About 11 mL/dL']],[HE],style='clinical_scenario')

q('A patient has ongoing major traumatic hemorrhage and shock. Which principle is most appropriate?', 'Rapid hemorrhage control with a protocolized blood-component/coagulation strategy rather than repeated large crystalloid loads alone',[
 ('Wait for a very low hemoglobin before considering major-hemorrhage treatment','Early hemoglobin can underestimate acute blood loss.'),('Use large crystalloid volumes as an equivalent replacement for oxygen-carrying and hemostatic components','Crystalloid does not replace those functions and excess can worsen dilution and edema.'),('Normalize every blood pressure with vasopressors while deferring bleeding control','This leaves the primary cause untreated.')],
 'Restore hemostasis and oxygen delivery while controlling the source','**Major bleeding requires coordinated resuscitation and definitive hemorrhage control.**',['Blood components or factor-guided strategies follow the local protocol and evolving tests.','Temperature, ionized calcium and coagulopathy need attention.'], '**Avoid resuscitation that delays source control.**',['Blood-pressure targets depend on context, especially traumatic brain injury.','Tranexamic acid timing is relevant in eligible bleeding trauma, but is not a substitute for hemostasis.'],[['Source','Control hemorrhage'],['Resuscitation','Oxygen-carrying and hemostatic needs'],['Safety','Temperature, calcium and coagulopathy']],[ref('European trauma bleeding guideline: sixth edition','https://pmc.ncbi.nlm.nih.gov/articles/PMC9977110/')],style='clinical_scenario')

q('For many septic resuscitation patients, which fluid is suggested over saline, with important context-specific exceptions such as traumatic brain injury?', 'A balanced crystalloid',[
 ('Hydroxyethyl starch','Starch is not a preferred sepsis resuscitation fluid because of harm concerns.'),('Hypotonic dextrose solution as the principal shock bolus','This does not provide an equivalent sustained intravascular resuscitation effect.'),('A synthetic gelatin as the preferred universal first choice','This is not the standard guideline-preferred approach.')],
 'Choose fluid composition as well as volume','**SSC suggests balanced crystalloid for many sepsis patients.**',['Patient-specific context, electrolyte status and brain injury can alter the choice.','An appropriate fluid type does not make an unnecessary volume safe.'], '**Reassess each bolus for benefit and harm.**',['Track perfusion, congestion and acid-base changes.','Do not treat all shock syndromes as identical to uncomplicated septic resuscitation.'],[['Balanced crystalloid','Often preferred in sepsis'],['TBI','Important composition exception'],['Volume','Still requires individual assessment']],[SS])

q('What is the most accurate interpretation of current temporary mechanical circulatory support evidence in cardiogenic shock?', 'Selected devices may benefit carefully selected patients, but routine deployment for every shock phenotype is unsupported and complications are substantial',[
 ('All devices have proven identical survival benefit in every cardiogenic shock patient','Device and population evidence differ.'),('DanGer Shock established benefit without increased adverse events','The trial found important safety trade-offs.'),('A negative trial for one device proves all mechanical support is ineffective in every selected patient','This overgeneralizes across mechanisms and populations.')],
 'Match the device to a defined phenotype and treatment goal','**Mechanical support is a selection and systems-of-care decision, not a universal shock reflex.**',['DanGer Shock supports a microaxial-pump strategy in a selected infarct-related shock population with increased adverse events.','Bleeding, ischemia, hemolysis and renal complications can offset benefit.'], '**Use a shock-team assessment and a bridge goal.**',['Consider RV/LV physiology, neurological prognosis, reversibility and center expertise.','Continue definitive cause treatment rather than regard a device as its replacement.'],[['Evidence','Population/device specific'],['Benefit','Possible in selected patients'],['Risk','Major procedural and organ complications']],[CS,ref('DanGer Shock original trial','https://www.nejm.org/doi/10.1056/NEJMoa2312572')])

q('A previously resuscitated patient is now hemodynamically stable but has substantial edema, positive balance and venous congestion. Which next fluid-management phase may be appropriate?', 'Avoid unnecessary intake and consider monitored fluid removal when the patient can tolerate it',[
 ('Continue repeated resuscitation boluses because the admission lactate was high','The current physiology should guide treatment.'),('Give diuretics during uncontrolled preload-dependent shock without reassessment','Fluid removal is not automatically safe during unresolved instability.'),('Ignore all fluid balance after MAP normalizes','Congestion and cumulative fluid can affect organ function.')],
 'The correct fluid strategy changes over the illness course','**Resuscitation, stabilization and de-resuscitation have different goals.**',['Diuresis or selected renal support may help when congestion persists and perfusion permits.','Not every edematous patient has adequate effective circulating volume.'], '**Monitor kidney function, pressure, electrolytes and response.**',['Reduce avoidable maintenance and drug-carrier fluid.','Adjust the removal rate if hypoperfusion develops.'],[['Early shock','Restore effective perfusion'],['Stable congestion','Consider removal'],['Monitoring','Balance decongestion and perfusion']],[HE,SS],style='clinical_scenario')

if __name__=='__main__':finalize('Critical Care and Toxicology',1,'Shock and Hemodynamic Support','critical-shock',rows,36)
